# BANF Portal Feature Test v2 - Correct endpoints + delays to avoid rate limiting$BASE = "https://banfwix.wixsite.com/banf1/_functions"$PASS = 0; $FAIL = 0; $TOTAL = 0function Test-Endpoint {    param($Label, $Url, $Method = "GET", $Body = $null, $ExpectCode = 200, $DelayBefore = 2)    Start-Sleep -Seconds $DelayBefore    $script:TOTAL++    try {        $params = @{ Uri = $Url; Method = $Method; TimeoutSec = 20; Headers = @{"Content-Type"="application/json"} }        if ($Body) { $params.Body = ($Body | ConvertTo-Json) }        $resp = Invoke-WebRequest @params -ErrorAction Stop        $code = $resp.StatusCode        $size = $resp.Content.Length        if ($code -eq $ExpectCode) {            Write-Host "[PASS] $Label : $code ($size bytes)" -ForegroundColor Green            $script:PASS++            return $resp.Content        } else {            Write-Host "[FAIL] $Label : got $code, expected $ExpectCode" -ForegroundColor Red            $script:FAIL++        }    } catch {        $code = $_.Exception.Response.StatusCode.value__        Write-Host "[FAIL] $Label : $code $($_.Exception.Message.Substring(0,[Math]::Min(60,$_.Exception.Message.Length)))" -ForegroundColor Red        $script:FAIL++    }    return $null}function Parse-Json($content) {    if ($content) { try { return $content | ConvertFrom-Json } catch { } }    return $null}Write-Host "`n===== BANF PORTAL FEATURE TEST v2 =====" -ForegroundColor CyanWrite-Host "Target: $BASE`n"# --- 1. LANDING PAGE ---Write-Host "`n[1] LANDING PAGE" -ForegroundColor Yellow$landing = Test-Endpoint "landing_page" "http://localhost:8900/banf-landing-preview-v2.html" -DelayBefore 0$ldata_raw = Test-Endpoint "landing_data_api" "$BASE/landing_data" -DelayBefore 2$ldata = Parse-Json $ldata_rawif ($ldata) {    $plans = $ldata.data.membershipPlans    Write-Host "  -> Plans ($($plans.Count)): $($plans | ForEach-Object { $_.name } | Join-String -Separator ' | ')"    $eb = $plans | Where-Object { $_.planId -like "*earlybird*" -or $_.name -like "*Early*" } | Select-Object -First 1    if ($eb) {        $pt = $eb.priceTable        Write-Host "  -> EB Price Table: Family:$($pt.family) Couple:$($pt.couple) Ind:$($pt.individual) Stu:$($pt.student)"    }}# --- 2. MEMBER PORTAL ---Write-Host "`n[2] MEMBER PORTAL" -ForegroundColor Yellow$mp = Test-Endpoint "member_portal_raw" "$BASE/member_portal_raw" -DelayBefore 3$profile = Test-Endpoint "member_profile_api" "$BASE/member_profile" -DelayBefore 3$payments = Test-Endpoint "member_payments_api" "$BASE/member_payments" -DelayBefore 2$mevents = Test-Endpoint "member_events_api" "$BASE/member_events" -DelayBefore 2$mdir = Test-Endpoint "member_directory_api" "$BASE/member_directory" -DelayBefore 2# --- 3. ADMIN PORTAL ---Write-Host "`n[3] ADMIN PORTAL" -ForegroundColor Yellow$adash_raw = Test-Endpoint "admin_dashboard_api" "$BASE/admin_dashboard" -DelayBefore 4$adash = Parse-Json $adash_rawif ($adash) { Write-Host "  -> Admin dashboard keys: $($adash.PSObject.Properties.Name -join ', ')" }$amembers = Test-Endpoint "admin_members_api" "$BASE/admin_members" -DelayBefore 3$apayments = Test-Endpoint "admin_payments_api" "$BASE/admin_payments" -DelayBefore 2$avendors = Test-Endpoint "admin_vendors_api" "$BASE/admin_vendors" -DelayBefore 2$asponsors = Test-Endpoint "admin_sponsors_api" "$BASE/admin_sponsors" -DelayBefore 2# --- 4. CRM ---Write-Host "`n[4] CRM" -ForegroundColor Yellow$crm_report = Test-Endpoint "crm_member_report" "$BASE/crm_member_report" -DelayBefore 4$crm_search = Test-Endpoint "crm_member_search" "$BASE/crm_member_search?query=test" -DelayBefore 3# --- 5. CHATBOT / RAG ---Write-Host "`n[5] CHATBOT (RAG)" -ForegroundColor Yellow$chats = @(    @{label="rag_ask_events"; body=@{query="What events does BANF have in 2026?"; context="general"}},    @{label="rag_ask_membership"; body=@{query="What are the membership tiers?"; context="general"}},    @{label="rag_ask_president"; body=@{query="Who is the BANF president?"; context="general"}})foreach ($c in $chats) {    $r = Test-Endpoint $c.label "$BASE/rag_ask" "POST" $c.body -DelayBefore 3    $rj = Parse-Json $r    if ($rj -and $rj.answer) { Write-Host "  -> Answer: $($rj.answer.Substring(0,[Math]::Min(80,$rj.answer.Length)))..." -ForegroundColor Cyan }}# Also try rag_query which is in http-functions.js$rq = Test-Endpoint "rag_query" "$BASE/rag_query" "POST" @{query="Tell me about BANF membership plans."} -DelayBefore 3$rqj = Parse-Json $rqif ($rqj -and $rqj.response) { Write-Host "  -> rag_query response: $($rqj.response.Substring(0,[Math]::Min(80,$rqj.response.Length)))..." -ForegroundColor Cyan }# --- 6. EVENTS ---Write-Host "`n[6] EVENTS" -ForegroundColor Yellow$events_r = Test-Endpoint "events_api" "$BASE/events" -DelayBefore 3$evj = Parse-Json $events_rif ($evj) { Write-Host "  -> Events: $($evj.events.Count) / total: $($evj.total)" }$past = Test-Endpoint "past_events_api" "$BASE/past_events" -DelayBefore 2# --- 7. RADIO ---Write-Host "`n[7] RADIO" -ForegroundColor Yellow$radio = Test-Endpoint "radio_schedule" "$BASE/radio_schedule" -DelayBefore 3$rstatus = Test-Endpoint "radio_status" "$BASE/radio_status" -DelayBefore 2# --- 8. ANNOUNCEMENTS ---Write-Host "`n[8] ANNOUNCEMENTS" -ForegroundColor Yellow$ann = Test-Endpoint "whatsapp_announcements" "$BASE/whatsapp_announcements" -DelayBefore 3# --- 9. MEMBER CHAT ---Write-Host "`n[9] MEMBER CHAT" -ForegroundColor Yellow$mchat = Test-Endpoint "member_chat" "$BASE/member_chat" "POST" @{message="Hello, what are BANF events?"} -DelayBefore 3# --- 10. LOCAL HTML FILES ---Write-Host "`n[10] LOCAL HTML FILES" -ForegroundColor Yellow$localFiles = @("member-portal.html","admin-portal.html","crm-admin.html","unified-ecosystem-dashboard.html","banf-landing-preview-v2.html")foreach ($f in $localFiles) {    $path = "banf1-wix\src\public\$f"    if (Test-Path $path) {        $sz = (Get-Item $path).Length        Write-Host "[PASS] local_$f : $sz bytes" -ForegroundColor Green        $PASS++; $TOTAL++    } else {        Write-Host "[FAIL] local_$f : NOT FOUND" -ForegroundColor Red        $FAIL++; $TOTAL++    }}# --- SUMMARY ---Write-Host "`n===== RESULTS =====" -ForegroundColor CyanWrite-Host "PASS: $PASS / $TOTAL  |  FAIL: $FAIL" -ForegroundColor $(if ($PASS -ge ($TOTAL*0.7)) { "Green" } else { "Red" })